      stock1: 'Nút "Thiết bị kho" tìm máy theo mã, tên; tick rồi bấm Chèn. Máy đã có trên bản vẽ được đánh dấu, không chèn trùng.',
      stock2: 'Hình của máy theo Loại thiết bị ở Danh mục; máy có ảnh thật thì hiện ảnh mặt trước.',
      cablesTitle: 'Vẽ dây là khai kết nối',
      cables1: 'Kéo dây nối hai máy kho thì IMS hỏi "Khai kết nối này vào sơ đồ cổng?" (cổng hai đầu và loại dây). Gõ tên cổng mới là cổng được tạo; cổng đã có cáp thì hộp báo ngay và gợi ý cổng trống.',
      cables2: '"Khai" ghi ngay vào sơ đồ cổng — kết nối nằm ở tab "Sơ đồ cổng" của trang thiết bị (lời báo có nút mở thẳng chỗ đó); "Chỉ vẽ" để nét vàng.',
      cables3: 'Xóa nét đã khai thì hỏi chỉ xóa nét hay gỡ luôn kết nối.',
      routeTitle: 'Bẻ dây cho vuông góc',
      route1: 'Dây đã khai là nét vuông góc. Muốn dây đi đường khác: chọn dây rồi kéo các chấm nhỏ trên chính dây (điểm uốn). Đừng vẽ thêm nét nối — nét tự do không mang kết nối, còn đầu dây kéo ra chỗ trống làm dây báo đỏ.',
      route2: 'Menu ⋮ › "Sắp lại dây" đổi mọi dây của kho trên trang sang nét vuông góc: giữ điểm uốn đang có, hoặc đi lại từ đầu (bỏ điểm uốn, nối lại đầu dây lệch về đúng máy của kết nối).',
      route3: 'Nhân bản hay dán một dây đã khai thì bản sao là nét tự do, không mang kết nối. Nét tự do chạm máy không phải lỗi.',
      framesTitle: 'Khung, tủ và vị trí U',
      frames1: 'Khung tòa nhà / tầng / phòng là hình chữ nhật tự do, chỉ để vẽ. Muốn xem chi tiết một tầng hay một phòng thì tạo bản vẽ con ở Cây bản vẽ.',
      frames2: '"Chèn tủ mạng" dựng khung tủ đúng số U từ kho; máy đặt theo U khai ở trang thiết bị, nhãn nằm bên phải. Máy đã có trên bản vẽ được dời vào khung (dây giữ nguyên); kéo máy vào khung thì IMS đặt lại đúng U. Máy kho ghi tủ khác thì IMS hỏi "Chuyển máy sang tủ này?" — chuyển thì ghi tủ và U mới vào kho, hủy thì máy ra ngoài khung. Bản vẽ cấp tủ có "Dựng lại mặt tủ" (giữ dây giữa các máy trong tủ).',
      navTitle: 'Tìm, chỉ đường, kiểm tra khớp',
      nav1: '"Tìm" bay tới một máy theo mã, tên hoặc IP; máy nằm ở bản vẽ khác thì mở bản vẽ đó.',
      nav2: '"Chỉ đường" tô đường dây giữa hai máy theo sơ đồ cổng.',
      nav3: '"Kiểm tra khớp" so bản vẽ với kho: máy thanh lý, đổi IP, kết nối mới chưa vẽ.',
      versionsTitle: 'Phiên bản và duyệt',
      versions1: 'Mỗi lần Lưu là một phiên bản nháp. Super Admin / Quản trị bấm Phát hành để thành bản chính thức; Thành viên Gửi duyệt nháp do mình lưu cho Quản trị.',
      versions2: '"Phiên bản" để xem, so sánh, đặt tên, khôi phục bản cũ.',
      presentationTitle: 'Bản trình bày',
      presentation1: '"Tạo bản trình bày" nhân bản bản chính thức thành bản tách rời để họp hay xin mua sắm: thêm máy dự kiến, ảnh tự do.',
      presentation2: 'Bản trình bày không qua duyệt, không đụng bản chính thức; file xuất ghi "BẢN TRÌNH BÀY".',
      mobileTitle: 'Xem trên điện thoại',
      mobile1: 'Màn hẹp chỉ có tab Xem: kéo để dời, chụm hai ngón để thu phóng, "Tìm" để bay tới một máy. Sửa bản vẽ cần màn máy tính.',
      menuTitle: 'Menu ba chấm (⋮)',
      menu1: 'Việc ít dùng nằm trong menu ⋮ cạnh nút Lưu, chia nhóm: Dây & kết nối · Xem & xuất · Khung, tủ & ảnh · Phiên bản & duyệt · Trợ giúp. Mỗi mục có một dòng nói việc đó làm gì.',
